test("直後の位置は、同じ親の 1 つ後ろになる", () => {
  const next = ChildPosition.next({ parentName: "panel", index: 2 });

  expect(next).toEqual({ parentName: "panel", index: 3 });
});

test("ロックした Box を起点に足す位置は、その Box の直後になる", () => {
  expect(DesignDocument.insertPositionOf(setupDocument(), "sealed")).toEqual(
    Option.some({ parentName: "panel", index: 1 }),
  );
});

test("ロックした Box の中のロックした Box を起点に足す位置は、最も外側のロックの直後になる", () => {
  expect(DesignDocument.insertPositionOf(setupDocument(), "inner")).toEqual(
    Option.some({ parentName: "panel", index: 1 }),
  );
});

test("祖先がロックしている Box は、自身にロックしていないと書いてあっても最も外側のロックの直後になる", () => {
  expect(DesignDocument.insertPositionOf(setupDocument(), "nested")).toEqual(
    Option.some({ parentName: "panel", index: 1 }),
  );
});

test("ロックしていない Box を起点に足す位置は、その Box の子の末尾になる", () => {
  expect(DesignDocument.insertPositionOf(setupDocument(), "open")).toEqual(
    Option.some({ parentName: "open", index: 1 }),
  );
});

test("artboard を起点に足す位置は、artboard の子の末尾になる", () => {
  expect(DesignDocument.insertPositionOf(setupDocument(), "home")).toEqual(
    Option.some({ parentName: "home", index: 4 }),
  );
});

test("ロックした Text には、子を持てないので足す位置が無い", () => {
  expect(
    DesignDocument.insertPositionOf(setupDocument(), "locked-title"),
  ).toEqual(Option.none);
});

test("ロックした部品インスタンスには、子を持てないので足す位置が無い", () => {
  expect(DesignDocument.insertPositionOf(setupDocument(), "login")).toEqual(
    Option.none,
  );
});

test("ドキュメントに無い名前には足す位置が無い", () => {
  expect(DesignDocument.insertPositionOf(setupDocument(), "missing")).toEqual(
    Option.none,
  );
});

test("ロックと書いた Box のノードはロックとして読まれる", () => {
  expect(
    Locking.fromNode({
      name: "panel",
      type: "Box",
      props: { locking: "locked" },
    }),
  ).toBe("locked");
});

test("参照ノード直下にロックと書いたインスタンスはロックとして読まれる", () => {
  expect(
    Locking.fromNode({
      name: "login",
      ref: "primary-button",
      locking: "locked",
    }),
  ).toBe("locked");
});

test("インスタンスの上書きにロックと書いても、インスタンスのロックにはならない", () => {
  expect(
    Locking.fromNode({
      name: "login",
      ref: "primary-button",
      overrides: { locking: "locked" },
    }),
  ).toBe("unlocked");
});

test("ロックした Box を選んで貼ると、その Box の直後に並ぶ", () => {
  const pasted = Option.unwrap(
    EditorState.pasteCopied(
      EditorState.select(setupNestedLockState(), "sealed"),
    ),
  );

  expect(childNames(pasted, "panel")).toEqual(["sealed", "source-2", "after"]);
});

test("祖先がロックしている Box を選んで貼ると、最も外側のロックの直後に並ぶ", () => {
  const pasted = Option.unwrap(
    EditorState.pasteCopied(
      EditorState.select(setupNestedLockState(), "nested"),
    ),
  );

  expect(childNames(pasted, "panel")).toEqual(["sealed", "source-2", "after"]);
});

test("ロックしていない Box を選んで貼ると、その Box の子の末尾に並ぶ", () => {
  const pasted = Option.unwrap(
    EditorState.pasteCopied(EditorState.select(setupNestedLockState(), "open")),
  );

  expect(childNames(pasted, "open")).toEqual(["open-title", "source-2"]);
});

test("ロックした Text を選んでいるときは貼れない", () => {
  expect(
    EditorState.pasteCopied(
      EditorState.select(setupNestedLockState(), "locked-title"),
    ),
  ).toEqual(Option.none);
});

test("ロックした Box を選んで Box を挿すと、その Box の直後に並ぶ", () => {
  const inserted = Option.unwrap(
    EditorState.insertNode(
      EditorState.select(setupNestedLockState(), "sealed"),
      { kind: "primitive", type: "Box" },
    ),
  );

  expect(childNames(inserted, "panel")).toEqual(["sealed", "box", "after"]);
});

test("ロックした Box を選んだまま 2 回貼ると、後に貼ったものが前に並ぶ", () => {
  const selected = EditorState.select(setupNestedLockState(), "sealed");
  const once = Option.unwrap(EditorState.pasteCopied(selected));

  const twice = Option.unwrap(EditorState.pasteCopied(once));

  expect(childNames(twice, "panel")).toEqual([
    "sealed",
    "source-3",
    "source-2",
    "after",
  ]);
});

test("ロックした Box の中の子を複製すると、複製はその Box の中の直後に並ぶ", () => {
  const duplicated = Option.unwrap(
    EditorState.duplicateSelected(
      EditorState.select(setupNestedLockState(), "inner"),
    ),
  );

  expect(childNames(duplicated, "sealed")).toEqual(["inner", "inner-2"]);
});

test("ロックした Box の上で離すと、並びへ挿す先にはその外側のロックしていない Box が選ばれる", () => {
  const parent = InsertionParent.innermost(
    setupLockedDocument(),
    moving("moved"),
    ["sealed", "panel", "home"],
  );

  expect(Option.unwrap(parent).name).toBe("panel");
});

test("祖先がロックしている Box は、自身にロックしていないと書いてあっても挿す先にならずロックの外側が選ばれる", () => {
  const parent = InsertionParent.innermost(
    setupLockedDocument(),
    moving("moved"),
    ["nested", "inner", "sealed", "panel", "home"],
  );

  expect(Option.unwrap(parent).name).toBe("panel");
});

test("座標の置き直しでも、ロックの中の Box の上で離すとロックの外側の親が選ばれる", () => {
  const parent = DropParent.innermost(setupLockedDocument(), moving("moved"), [
    "inner",
    "sealed",
    "panel",
    "home",
  ]);

  expect(Option.unwrap(parent).name).toBe("panel");
});

test("artboard 直下のロックした器の上で離すと、置き直し先は artboard になる", () => {
  const parent = DropParent.innermost(setupLockedDocument(), moving("moved"), [
    "free-lock",
    "home",
  ]);

  expect(Option.unwrap(parent).name).toBe("home");
});

test("パレットの雛形を運んでいるときも、ロックの中の Box は挿す先にならない", () => {
  const parent = InsertionParent.innermost(setupLockedDocument(), placingBox, [
    "nested",
    "inner",
    "sealed",
    "panel",
    "home",
  ]);

  expect(Option.unwrap(parent).name).toBe("panel");
});

test("ロック中の Box を子に持つ Box は落とし先のまま選ばれる", () => {
  const parent = InsertionParent.innermost(
    setupLockedDocument(),
    moving("moved"),
    ["panel", "home"],
  );

  expect(Option.unwrap(parent).name).toBe("panel");
});

test("フローのノードをロックの中の Box の上で離すと、ロックの外側の Box の子になる", () => {
  const onMoveNode = vi.fn();
  renderCanvas({ selection: setupSelection(), onMoveNode });

  dragNodeOnto("title", drawn("inner"), { x: 30, y: 40 });

  expect(onMoveNode).toHaveBeenCalledWith(
    "title",
    expect.objectContaining({ parentName: "panel" }),
  );
});

test("絶対配置のノードをロックの中の Box の上で離すと、ロックの外側の Box へ親が付け替わる", () => {
  const onRepositionNodes = vi.fn();
  renderCanvas({ selection: setupSelection(), onRepositionNodes });

  dragNodeOnto("pin", drawn("inner"), { x: 30, y: 40 });

  expect(onRepositionNodes).toHaveBeenCalledWith([
    expect.objectContaining({
      name: "pin",
      edit: expect.objectContaining({
        to: expect.objectContaining({ parentName: "panel" }),
      }),
    }),
  ]);
});

test("ロックの中の Box の上へ運んでいる間、落とし先の枠はロックの外側の Box に出る", () => {
  renderCanvas({ selection: setupSelection() });

  pressPointer(drawn("title"), { x: 100, y: 100 });
  movePointer(drawn("inner"), { x: 130, y: 140 });

  expect(injectedStyles()).toContain('[data-name="panel"]{outline:2px dashed');
});

test("プリミティブの行をロックの中の Box へ運んで離すと、ロックの外側の Box の子に増える", async () => {
  await renderOpenedDocument(
    DesignDocument.create({
      tokens: DocumentTemplate.Default.tokens,
      components: DocumentTemplate.Default.components,
      artboards: [
        Artboard.create({
          name: "home",
          width: 360,
          height: 240,
          children: [
            {
              name: "home-panel",
              type: "Box",
              children: [
                {
                  name: "home-sealed",
                  type: "Box",
                  props: { locking: "locked" },
                  children: [{ name: "home-inner", type: "Box", children: [] }],
                },
              ],
            },
          ],
        }),
      ],
    }),
  );
  await goTo(LeftPaneViews.Assets);

  carryTo("Box", drawn("home-inner"));
  releasePointer(drawn("home-inner"), { x: 300, y: 150 });

  expect(drawnParentName("box")).toBe("home-panel");
});

test("ツリーでロックの中の Box を選んで貼ると、ロックの外側の Box の中に描かれる", async () => {
  await renderOpenedDocument(setupNestedLockDocument());
  await selectInTree("home-note");
  await userEvent.keyboard("{Control>}c{/Control}");
  await selectInTree("home-inner");

  await userEvent.keyboard("{Control>}v{/Control}");

  expect(drawnParentName("home-note-2")).toBe("home-panel");
});

test("ツリーでロックの中の Box を選んで Box を追加すると、ロックの外側の Box の中に描かれる", async () => {
  await renderOpenedDocument(setupNestedLockDocument());
  await selectInTree("home-inner");

  await userEvent.click(
    within(canvasPane()).getByRole("button", { name: "Box を追加" }),
  );

  expect(drawnParentName("box")).toBe("home-panel");
});

test("ツリーの行を運ぶと、ロック中の Box の中の子も並べ替えられる", async () => {
  await renderOpenedDocument(setupNestedLockDocument());

  dragRowNamed(tree(), { from: "home-inner", to: "home-caption" });

  expect(rowNames(tree())).toEqual([
    "home-note",
    "home-panel",
    "home-sealed",
    "home-caption",
    "home-inner",
  ]);
});

